// Single source for the sidebar topics, their groups and the breadcrumbs.
// Imported by astro.config.ts (through src/lib/sidebar.ts), src/routeData.ts and the PageTitle override.

export type Localized = { en: string; vi: string }

export type SidebarSpec =
  /** A collapsible group autogenerated from one directory. */
  | { kind: 'group'; label: Localized; directory: string; collapsed: boolean }
  /** Pages of one directory listed at the top level of the topic. */
  | { kind: 'flat'; directory: string }
  /** A group of pages that live in another topic (Starlight localizes `slug` entries). */
  | { kind: 'links'; label: Localized; slugs: string[]; collapsed: boolean }
  /** The generated API reference group (starlight-openapi). */
  | { kind: 'api'; label: Localized; directory: string }

export type Topic = {
  id: string
  label: Localized
  link: string
  icon: string
  /** First path segments that belong to this topic. */
  dirs: string[]
  sidebar: SidebarSpec[]
}

const group = (en: string, vi: string, directory: string, collapsed = true): SidebarSpec => ({
  kind: 'group',
  label: { en, vi },
  directory,
  collapsed,
})

